        "display": "center",
        "content": [
            {
                "line": "早岁那知世事艰，中原北望气如山。",
                "trans": "年轻时哪里知道世事如此艰难，北望中原，收复故土的豪迈气概坚定如山。",
                "pinyin": ""
            },
            {
                "line": "楼船夜雪瓜洲渡，铁马秋风大散关。",
                "trans": "记得曾在瓜洲渡痛击金兵，车船在雪夜里飞奔。秋风中骑着战马纵横驰骋， 收复了大散关，捷报频传。",
                "pinyin": ""
            },
            {
                "line": "塞上长城空自许，镜中衰鬓已先斑。",
                "trans": "当年曾以守城大将檀道济自我期许，到如今鬓发渐白，盼望收复故土的愿望已成空谈。",
                "pinyin": ""
            },
            {
                "line": "出师一表真名世，千载谁堪伯仲间。",
                "trans": "",
                "pinyin": ""
            }
        ],
